LESSONS = [
 dict(id='C03', title='接入现成角色：会选、会替换、会验收', prereq=['B13'], concepts='KN21/KN15/KN26', goal='判断两份角色资产哪份更适合当前原型，并制定替换验收单。',
 m=['核对比例、朝向、骨骼与动作兼容，选择可用资产。','替换视觉角色而保持控制与碰撞职责。'], k=['Armature/Skeleton、Skin/Weights分别是骨架、蒙皮与影响权重。'], stop='不从零绑定和全面刷权重；复杂坏资产允许合理弃用。',
 body=['角色文件看起来完整，不代表包含可用动画或符合现有骨架。先试一小段待机和行走，再决定是否值得整套导入。','碰撞胶囊、移动根节点与视觉角色分开，可避免为了角色身高误改所有物理参数。角色极端比例可能让自动绑定或重定向不适用。'],
 initial='两份教学资产卡：A比例合适且有骨架/待机，B高细节但无骨架；预览用简化人物，真实资产未附时不冒充导入成功。', controls='显示包内容、比例0.8到1.2、前向箭头、待机/行走预览、碰撞可视化。', steps=['按用途列选择条件，不先按面数或精细度选。','只替换视觉并核对脚底、胶囊和前向。','播放两段动作，发现问题后选择小修还是换资产。'], feedback='展示来源、授权状态、骨骼和动作信息；教学卡数据标示意。', failure='故障：为了缩小人物把控制根节点整体缩放，碰撞也变形；恢复职责后只修正确资产层。', reset='恢复胶囊占位人与原控制参数，替换资产保留副本。', ui=['常用：角色视觉Transform、动画预览、碰撞可见性。','会定位：导入骨架、动画列表和源文件信息。','按需查：重定向映射、蒙皮修复；不是必背工具。'],
 questions=[('P','一个漂亮模型没有骨架，是否一定更适合先做走路角色？','不一定；实现成本可能高于有兼容骨架的简单角色。','优先满足什么用途？'),('D','换角色后碰撞与脚底不一致，先查什么？','视觉原点、比例、位置与控制根的关系，避免直接乱改移动代码。','哪个节点被缩放了？'),('T','换成头更大的卡通人物，哪些检查不能省？','动作变形、脚滑、碰撞、前向、镜头可读性以及授权。','外形变化会影响哪些表现？'),('K','Weights是什么用途？','决定骨骼对网格的影响程度，出现变形问题时查，不要求此刻手刷。','先分清骨架和网格。')], remember=['先试最小动作再批量导入。','视觉与碰撞职责分开。','资产不合适可以换，不必硬修。'], recall=['B02','B05'], practice='后续配套阶段选择真实可授权角色；本课不分发第三方角色包。', sources=['retarget','mixamo']),
 dict(id='C04', title='动画状态：动作片段如何接起来', prereq=['C03'], concepts='KN21/KN16', goal='设计待机、走跑、跳落地的切换条件，排除抖动与错切。', m=['用状态和条件选择片段，区分动画表现与角色运动。','调过渡时间并检查连续动作。'], k=['Root Motion/IK/Blend分别是位移来源、局部约束和混合思路。'], stop='不推动画混合算法，不强制Root Motion实现。',
 body=['AnimationPlayer保存片段，AnimationTree可组织混合和状态切换。脚本控制器与动作片段可能都含位移，要明确谁控制根移动。','状态条件优先于过渡好看：落地才回到移动，速度接近零时避免在待机和走之间抖动。短过渡不必越长越柔和。'], initial='待机/走/跑/跳四卡，speed=0、grounded=true；用简化骨架或时间条，不伪称真实动画素材。', controls='速度0到7、grounded开关、过渡0到0.4秒、连续输入测试。', steps=['写三个切换条件后再连线。','连续启停和跳落地，读状态日志。','只改变过渡时长，看过长过渡是否让动作迟钝。'], feedback='当前状态、条件与片段时间同时显示；动画与位置分别显示。', failure='故障：空中speed=0时错误回Idle；应纳入落地条件。', reset='清空状态机回到站立初态，恢复速度和过渡。', ui=['常用：片段预览、状态条件、过渡时间。','会定位：AnimationPlayer/AnimationTree与参数面板。','按需查：BlendSpace、Root Motion提取、IK算法。'],
 questions=[('P','空中水平速度为零就应待机吗？','不应仅据此切待机，还要考虑是否落地。','有哪些条件？'),('D','人物走路脚滑一定是模型坏了吗？','不一定；检查移动速度与片段节奏、位移来源、重定向。','先看最小对照。'),('T','新增慢走片段，怎样验证没有破坏跳跃？','调整速度条件并回归启停、空中与落地，不只看慢走单播。','哪些状态受影响？'),('K','Root Motion大概指什么？','从动作中提取角色根位移；与脚本位移需协调，不要求自行实现。','谁负责移动？')], remember=['先对条件，再调过渡。','动作播放不等于移动正确。','避免双重根位移。'], recall=['B06','A06'], practice='后续使用现成动画，学员只调条件与节奏。', sources=['anim','retarget']),
 dict(id='C05', title='复用与资源：共享什么、独立什么', prereq=['C04'], concepts='KN05/KN17', goal='给三个同类物体制定共享资源和独立状态方案。', m=['区分共享材质/配置与独立的运行状态。','限定修改影响范围并验收。'], k=['深浅复制、Resource缓存用来解释影响，不背实现。'], stop='不考设计模式名字，不复制所有纹理来保证安全。', body=['三个场景实例可以有独立位置和状态，同时引用同一材质。是否共享由需求决定，不是共享一定好或全部独立更安全。','复用的关键是改通用规则方便，改个别实例不串改。运行时生命、是否拾取等状态不应无意写入全体共享配置。'], initial='三棵树共用材质，三份拾取状态独立；给出资源引用图。', controls='改共享颜色、独立颜色、单件消耗、复制配置按钮。', steps=['预测一次颜色修改影响几棵树。','只让一棵树变秋色，保持其他共享。','消耗一个对象，检查另外两个状态不变。'], feedback='引用连线与受影响对象高亮同步；只统计真实状态变化。', failure='故障：consumed放入共享Resource导致全部消失；修改状态归属。', reset='恢复引用与独立状态；不通过整套复制隐藏错误。', ui=['常用：Inspector资源引用、Make Unique或等效操作。','会定位：资源文件与实例覆盖。','按需查：嵌套资源复制规则。'], questions=[('P','实例不同，材质就一定不同吗？','不一定，可能共享引用。','查看连线。'),('D','拿一个道具其他都不可用，先看哪里？','检查运行状态是否误放入共享资源。','谁拥有consumed？'),('T','一百个同类瓶子只改一个标签，怎么避免重复大纹理？','复用公共资源并局部覆盖需要独立的部分，验证范围与成本。','哪些是真正不同的？'),('K','深复制为什么值得按需查？','嵌套资源未必随外层独立；遇到串改时查规则。','不是要求背定义。')], remember=['实例独立不代表资源全独立。','共享配置不等于共享运行状态。','按影响范围决定复制。'], recall=['B04','B06'], practice='后续在实际资源图上做一处独立化；无需自建组件框架。', sources=['resource']),
 dict(id='C06', title='门与移动平台：复用已会的空间和状态', prereq=['C05'], concepts='KN04/KN07/KN16', goal='设计一扇可重复触发的门，识别移动平台的额外验收项。', m=['组合支点、条件和状态，避免重复触发冲突。','检查站上、离开、阻挡和恢复等边界。'], k=['AnimatableBody3D等物理类型按实际运动方式查。'], stop='本课门为主任务；平台作为给定示例验收，不写通用平台物理系统。', body=['门的支点、运动和是否可通过是相互关联但不同的事情。开门动画播了不等于碰撞已正确让路。','移动平台需要考虑角色站在上面和离开时的运动；只看平台来回动不算完成。先列需要检查的情况再让AI实现。'], initial='侧边支点门、closed/opening/open状态卡；另有可选平台示意。', controls='开门、重复按、角度0到90、持续时间0.3到2秒、恢复；平台站上/离开卡。', steps=['预测opening期间再次触发应如何处理。','播放、重复触发、检查可通过时机。','用平台情境卡补站立、边缘离开和重开检查。'], feedback='门角、状态、可通过标记分别显示；平台动态为示意不做物理性能保证。', failure='故障：重复触发叠加Tween导致门越转越远；改为绝对目标和状态约束。', reset='门角、状态和碰撞一致回到关闭；平台回起点。', ui=['常用：支点Transform、时间、状态条件。','会定位：碰撞、动画轨道与物理体类型。','按需查：平台速度继承与复杂物理API。'], questions=[('P','门动画播完就能证明玩家能通过吗？','不能，还要验证碰撞与通行。','视觉与物理分开。'),('D','反复按键门越转越远，如何缩小问题？','检查增量叠加和重入，使用明确目标角与状态。','有没有固定结束状态？'),('T','升降机需要增加什么验收？','站上跟随、离开、夹住风险与重开恢复；仅有上下运动不够。','玩家与平台如何交互？'),('K','为什么查专用运动物理体？','不同运动方式与物理同步有不同适用类型。','不背类型全集。')], remember=['重复输入必测。','动画和通行分别检查。','平台要带着角色验收。'], recall=['A07','B06'], practice='后续先交付门，平台复杂表现有需求再做。', sources=['node','body','anim']),
 dict(id='C07', title='模块拼接与简单UV：统一尺度和纹理密度', prereq=['C05','B05'], concepts='KN14/KN22', goal='把三块墙拼齐，并让棋盘格在它们表面大小接近。', m=['按统一尺寸和原点对齐模块。','用棋盘格识别拉伸与密度问题，修一个简单UV。'], k=['Texel Density、Trim Sheet、Decal只认识适用问题。'], stop='不展开复杂人物UV，不做完整贴图绘制课程。', body=['模块化依赖尺度、原点和连接规则一致。几何拼齐后，纹理仍可能因UV分配不同而大小不一致。','棋盘格用于检查映射：拉长的格子提示拉伸，格子尺寸不同提示密度不一致。升高贴图分辨率不能替代修正映射。'], initial='三块2米墙，两块UV一致，一块横向拉伸；原点标在底边角。', controls='吸附步长0.5/1、模块旋转90度、UV宽度0.5到2、棋盘格/成品切换。', steps=['先拼几何，确认无缝隙后再看纹理。','只改变错误墙的UV比例，检查格子接近正方形。','转一块墙构成角落，检查接缝和图案方向。'], feedback='显示世界尺度和UV比例两个独立信息；网页映射仅示意，真机复核另列。', failure='故障：墙纹理拉伸，AI仅把图片升4K；指出原因未修。', reset='恢复墙位置、UV和检查材质，保留一张对照。', ui=['Blender：UV Editor、缩放简单UV岛、棋盘格预览。','会定位：吸附、对象Dimensions、图像贴图。','按需查：自动展开、复杂接缝、Trim Sheet流程。'], questions=[('P','同一张贴图用在三堵墙上，清晰程度一定相同吗？','不一定，UV分配与世界尺寸都会影响。','比较格子大小。'),('D','格子拉长，升分辨率能解决吗？','不能解决映射拉伸；先改UV或尺度关系。','像素多了会改变比例吗？'),('T','做直墙和转角套件应统一什么？','尺寸、连接点、原点、纹理密度与材质风格。','从拼接到表面都检查。'),('K','Trim Sheet适合什么思路？','多个模块共享一组条带纹理以复用细节；有需求再学。','不是本课强制制作。')], remember=['先拼几何，再看表面。','清晰度不只看分辨率。','棋盘格是诊断工具。'], recall=['B05','B02'], practice='后续只要求简单墙面UV操练，复杂人物不作门槛。', sources=['gltf','blender']),
 dict(id='C08', title='风格化光照方案：效果必须能进游戏', prereq=['C07','B09'], concepts='KN25', goal='在两种照明方案中选一个适合动态角色和目标设备的方案。', m=['比较方案的表现、动态支持和成本。','核对Blender展示与Godot实际渲染的差异。'], k=['Lightmap/GI/反射探针知道用途即可。'], stop='不要求搭建所有GI技术，不学习光传输推导。', body=['展示渲染和实时游戏的约束不同。静态背景可采用的光照方法不必同样适用于移动角色。','选择一种最简单可行方案，固定相机与材质比较。缺阴影、色彩管理或环境不同都可能改变观感，不该用无穷加灯掩盖。'], initial='固定童话小屋场景；A简易实时主光，B带静态烘焙背景的方案卡；角色可移动。', controls='A/B切换、移动角色、昼夜改变开关、成本记录标签。', steps=['先列动态需求和目标设备，再选候选。','检查角色经过阴影和亮区时是否合理。','记录与Blender参考的差异，按材质/环境/灯光分类。'], feedback='未真实测量的耗时只标教学估算；不把方案卡数值写成性能结论。', failure='故障：把静态烘焙结果当可任意移动的实时光，变化后照明不对应；重新匹配需求。', reset='恢复同一机位、材质和角色位置。', ui=['Godot：环境与灯光基础设置、目标渲染器。','会定位：Lightmap/GI开关及支持范围。','按需查：烘焙参数、反射更新、阴影过滤。'], questions=[('P','背景看起来完美能说明移动角色也合适吗？','不能，要测试角色穿过不同照明区域。','静态与动态分开。'),('D','Blender柔和但游戏很硬，先怎样检查？','固定样本，核对灯光环境、材质与色彩处理，不只加亮。','哪些条件未一致？'),('T','加入可移动太阳后原方案要补什么验证？','动态照明与阴影更新、性能和视觉一致性。','方案依赖静态假设吗？'),('K','Lightmap大致是什么？','储存预先计算照明的一类贴图方案，按动态需求判断适用性。','无需推导。')], remember=['展示渲染不等于游戏渲染。','动态物体单独验收。','先选可行方案，不把技术全用上。'], recall=['B09','B11'], practice='后续只实施一种选定方案；课堂先完成取舍练习。', sources=['perf','gltf']),
 dict(id='C09', title='优化入口：知道什么时候该停', prereq=['C08'], concepts='KN19/KN29/KN30', goal='从一个症状提出可检验的瓶颈假设，避免无差别优化。', m=['区分测量条件、症状、假设和结论。','在满足目标时停止不必要的优化。'], k=['MultiMesh/LOD/剔除/资源驻留用来选择下一份文档。'], stop='中级不实现完整大世界流送；高级专项按需再做。', body=['慢可能来自脚本、物理、绘制、加载或资源驻留。只知道面多不够，要用对应开关和记录缩小问题。','一个优化可能减少绘制次数却增加其他约束；成功要看目标帧时间与可读性，不只看一个指标下降。'], initial='三组明确标示合成的案例：大量对象、首次加载尖峰、透明叠加；每组含帧时间和行为标签。', controls='隐藏一组对象、预热与首次运行比较、固定相机路径、A/B记录。', steps=['先指出数据能支持什么，不能支持什么。','挑一个最小改变验证原因，避免同时改资源和画质。','目标达标后写停止理由或下一实验。'], feedback='不展示虚构硬件测试；所有成本样本标示意。', failure='故障：只因Draw Call高就改成全场一个批量对象，却不再有效剔除；讨论测量而不是口号。', reset='恢复原样本与条件。', ui=['常用：Profiler/Monitors、效果或对象组开关。','会定位：CPU/GPU相关记录与加载日志。','按需查：MultiMesh、LOD、剔除和异步加载API。'], questions=[('P','三角形少就一定快吗？','不一定，还有提交、像素、脚本、加载等成本。','数据还缺什么？'),('D','优化后指标下降但体验更卡，怎么验收？','回看真实目标和帧时间分布，检验副作用并回退。','你优化的是指标还是体验？'),('T','只有第一次进入场景卡，先做什么对照？','区分首次加载与预热运行，记录加载/编译相关证据再下结论。','稳定运行是否也卡？'),('K','MultiMesh适合什么方向？','大量相似实例的批量绘制；剔除范围和独立行为限制要查。','不是默认全场打包。')], remember=['先找症状再选工具。','优化要看副作用。','达标可以停止。'], recall=['B11'], practice='后续真实数据替换教学案例；不强制GPU抓帧。', sources=['perf']),
 dict(id='E01', title='导航选修：画得出路径还要走得到', prereq=['C09'], concepts='KN23', goal='判断导航路径与物理通行是否一致。', m=['选择本项目是否需要导航。','选择后，检查巡逻追踪的实际可达性。'], k=['NavMesh、避障、寻路各有不同职责。'], stop='纯机关路线可跳过；不实现A*和复杂敌人AI。', body=['导航描述可以规划的空间，碰撞负责真实阻挡，两者不自动一致。看见路径线不等于角色能通过。','动态门、角色体积和窄通道都可能让计划与执行不一致。先做简单巡逻或追踪，再考虑战斗。'], initial='平面地图、有墙和一扇门；规划线、实际轨迹两种显示。', controls='门开/关、通道宽度、角色半径、目标点、重规划。', steps=['先预测窄通道是否能过。','比较规划线和实际轨迹，改变门状态再测试。','确定纯机关项目是否可以跳过本专题。'], feedback='标出规划失败/移动受阻而非一律敌人AI坏了；简化2D足够，不强制3D。', failure='故障：导航区域穿墙而物理墙存在；修两者一致性，不删墙。', reset='恢复地图、半径、门和起终点。', ui=['Godot：导航预览、目标点、角色体积和碰撞。','会定位：NavigationRegion3D/NavigationAgent3D。','按需查：网格烘焙、避障参数。'], questions=[('P','路径线穿过门能保证走过吗？','不能，门状态与碰撞仍可能阻挡。','看实际轨迹。'),('D','角色一直顶墙，先核对什么？','规划空间与物理空间、体积和门状态，不先重写算法。','哪个系统认为可走？'),('T','通道变窄后要重新验收什么？','角色体积、导航可达性和实际通过，必要时改路线。','不只移动目标点。'),('K','避障与寻路是否同一件事？','不是，整体路线和局部避让关注不同问题。','一个决定去哪，一个处理附近什么。')], remember=['路径线不是通行证。','导航与碰撞要一致。','无敌人需求可以跳过。'], recall=['A04','C09'], practice='后续有导航需求才制作配套示例。', sources=['body','perf']),
 dict(id='C10', title='可交互对象：提示、条件和结果', prereq=['C06'], concepts='KN16/KN17', goal='让一个开关或门可理解地交互，并拒绝距离外操作。', m=['把目标提示、可交互条件和状态结果对应起来。','复用一条交互链而不让对象乱改全局UI。'], k=['射线检测是一种选择目标的方法。'], stop='不要求通用背包，亦不依赖导航选修。', body=['提示告诉玩家现在能做什么，条件决定是否真的能做。提示出现但按键无效，或远处也能触发，都破坏可理解性。','对象报告交互结果，UI呈现提示；状态归属要明确。钥匙需求可以先用布尔条件模拟，不因此展开完整物品系统。'], initial='门与按钮两个目标，距离与视线标签；一次只允许一个当前目标。', controls='距离1到5、视线遮挡、交互键、locked条件、提示开关。', steps=['先预测距离外或被遮挡时的结果。','比较提示与实际触发；改变目标确保旧提示消失。','把按钮换成宝箱，复用条件链而改变结果。'], feedback='每次失败有可理解原因，但不泄露不该显示的游戏信息；日志与状态对应。', failure='故障：目标已离开但旧提示仍在，按键修改旧对象；清理当前目标与UI。', reset='清空目标、提示和对象状态。', ui=['Godot：检测距离、对象组、提示文本和状态条件。','会定位：RayCast3D结果和信号。','按需查：完整交互框架。'], questions=[('P','显示按E是否就表示条件有效？','应该一致但不能假定实现正确，要测试距离/遮挡/状态。','提示和条件都检查。'),('D','离开门后仍操作旧门，优先查什么？','当前目标引用与提示清理，是否验证对象有效和范围。','哪个状态过期？'),('T','按钮改成一次性宝箱，增加什么检查？','消耗/已打开状态、重复输入、提示变化和结果归属。','复用B06的哪部分？'),('K','射线在交互中有什么用途？','确定视线指向的对象和距离，是目标选择手段之一。','不是必须唯一方案。')], remember=['提示与可操作条件一致。','目标过期要清理。','对象状态不藏在UI。'], recall=['B06','C05'], practice='后续可用开关作为最小实现，不先做背包。', sources=['area','resource']),
 dict(id='C11', title='存档与设置：能恢复比能写入更重要', prereq=['C10'], concepts='KN24', goal='定义最小保存内容，并用三份给定数据检查恢复。', m=['区分持久进度、偏好设置和临时状态。','测试缺失/旧版/损坏数据的恢复策略。'], k=['版本迁移、原子写入是避免破坏保存数据的思路。'], stop='不做数据库、云同步或安全加密课程。', body=['保存不是把所有节点照相。最小进度与设置应明确，例如已完成目标ID、音量和输入偏好；临时粒子和鼠标位置通常不是必须存。','读取失败时要有可解释退路，不静默覆盖用户原文件。旧数据要按版本判断，复杂迁移可交AI写但测试由人定义。'], initial='三张教学JSON数据卡：正常、缺字段、无效内容；只在沙盒模拟，不读取真实用户文件。', controls='选择数据、加载、默认值、保留原件、改变音量、重开。', steps=['先分类哪些需要持久保存。','加载三种数据，记录提示与恢复状态。','修改一个设置后重开，检查与进度互不误伤。'], feedback='显示解析结果、采取的策略及是否覆盖原件；失败不可伪装成功。', failure='故障：损坏档加载失败后立刻写空档覆盖；要求保留原件并提供恢复路径。', reset='只清沙盒数据，保留模拟备份和错误记录。', ui=['Godot：设置参数、模拟加载按钮、错误输出。','会定位：user://数据位置概念、配置与进度文件。','按需查：序列化API、迁移和原子写入实现。'], questions=[('P','粒子当前播放时间一定要保存吗？','不一定，按恢复需求选择，不无差别存所有状态。','玩家下次真正需要什么？'),('D','加载失败自动覆盖空档，问题在哪？','可能毁掉可恢复数据；先保留原件、报告并选恢复策略。','数据是否还能找回？'),('T','游戏新增字段，旧档怎么验收？','提供默认或迁移策略，测试旧档、正常档与损坏档，不只写新格式。','兼容对象是谁？'),('K','数据版本号的用途？','帮助区分保存格式并选择恢复/迁移方案。','不要求数据库知识。')], remember=['先定义需要恢复什么。','失败不要覆盖唯一原件。','读档边界与写档同样重要。'], recall=['B08','B12'], practice='真实存档实现推迟到配套阶段；本课不动个人数据。', sources=['resource']),
 dict(id='C12', title='交付：别人电脑上第一次运行', prereq=['C11','C09'], concepts='KN20/KN24/KN26', goal='写出选定平台的首次启动与完成路径验收单。', m=['在干净环境检查依赖、输入、资源与结束路径。','核对来源、可分发范围和已知限制。'], k=['Debug/Release、导出模板和平台签名知道入口即可。'], stop='只选一个目标平台，不学全部商店运营和签名体系。', body=['编辑器里能玩不等于导出包能玩。干净用户数据、资源路径大小写、导出包含范围和输入设备可能暴露遗漏。','课程公开仓库与游戏发布包的授权需求也可能不同。可在游戏使用不必然可在源码仓库再分发源资产，按具体许可核对。'], initial='两张包清单：只含游戏包与误包含本地绝对路径的包；首次启动/老用户两种场景。', controls='干净/已有存档、目标平台、资源包含勾选、完成/退出步骤。', steps=['画一次从打开到完成再退出的路径。','用清单查缺失依赖和硬编码路径。','核对每份资源的来源、修改和再分发记录。'], feedback='明确课堂不真的导出或验证某平台，输出待执行验收单。', failure='故障：仅作者电脑有的一张贴图被漏打包；修导出依赖而非让用户手工复制私人目录。', reset='还原包清单与测试数据，不修改真实系统。', ui=['Godot：Export目标、资源包含范围、Release/Debug用途。','会定位：首次启动日志、数据目录。','按需查：安装签名、平台权限和商店要求。'], questions=[('P','本机编辑器跑通等于发布包通过吗？','不等于，要测干净环境实际包。','环境有哪些不同？'),('D','换电脑模型缺贴图，先查什么？','资源依赖和打包范围、路径，不先重做模型。','作者电脑独有了什么？'),('T','教程仓库准备公开，资源已可商用就都能上传吗？','不能一概而论；单独核对源文件再分发权限。','发布游戏与发布素材有什么不同？'),('K','Release与Debug为何区分？','用途与调试信息等不同，交付要测试实际版本。','不要只测编辑器。')], remember=['测试别人第一次运行。','导出包才是交付对象。','使用权和源资产再分发分开核对。'], recall=['B05','B11','C11'], practice='平台实际导出和法律判断需对应执行/许可文本；课程不作普遍许可保证。', sources=['kenney','mixamo','perf']),
 dict(id='D07', title='中级结业：小型原型的完整闭环', prereq=['C12','C04','C06'], concepts='KN16/KN21/KN24/KN25/KN26', goal='提交一条可完成、可恢复、可解释的小型原型路径。', m=['整合正式角色、目标、交互和恢复；根据项目选机关或导航。','提供功能、可读性、性能与交付证据。'], k=['只抽已选路线的用途词；未选导航和高级专题不考。'], stop='不同时强制敌人、机关、战斗、多人；控制原型范围。', body=['中级不是功能越多越好，而是少量功能连接可靠。一个清楚的目标、一种交互、合理反馈、失败恢复比五个未完成系统更有价值。','已有初级证据可复用，只抽关键变式。评价包括解释取舍，而不是要求学员从空白手写所有脚本。'], initial='两条范围卡：机关解锁出口，或简单巡逻避让；两者选一，不要求同时做。', controls='选择路线、关键测试抽签、保存/重开、窄窗口、条件记录。', steps=['写一个最小完成路径和不做清单。','按路径测试一次正常和一个关键异常。','隔次改变一个对象/约束，检查方案是否仍适用。'], feedback='分别标材料齐全、技术通过、人工通过、学习迁移；不把一项代替另一项。', failure='故障：为赶完成删除失败恢复；重新限定范围而不删底线。', reset='保留可交付基线，撤回未完成实验。', ui=['只复用已学界面和参数。','会定位：打包与证据记录。','按需查：实现代码和具体平台选项。'], questions=[('P','系统数量多是否代表更合格？','不代表，评价完整路径与可靠性。','哪些真的能结束？'),('D','原型功能正常但无法重开，属于可忽略问题吗？','对设定需要重开的原型不是；要验证恢复路径。','完整闭环包含什么？'),('T','把目标从收集改为启动两台装置，如何迁移？','复用状态、条件、反馈和保存，改目标定义并回归完成条件。','哪些逻辑不必重造？'),('K','没有选导航要实现寻路吗？','不需要，未选路线不进入本次毕业条件。','范围由什么决定？')], remember=['少而完整胜过多而破碎。','各类验证分别记录。','未选的高级知识不阻塞交付。'], recall=['B13','C11','C12'], practice='结业项目是后续实作任务，此课件不宣称已有成品。', sources=['perf','resource'])
]
